#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "cJSON.h"
#include "lodepng.h"

#define INPUT_DIM 784
#define HIDDEN_DIM 128
#define NUM_CLASSES 10

float input_layer_weight[HIDDEN_DIM][INPUT_DIM];
float input_layer_bias[HIDDEN_DIM];
float hidden_layer_weight[HIDDEN_DIM][HIDDEN_DIM];
float hidden_layer_bias[HIDDEN_DIM];
float output_layer_weight[NUM_CLASSES][HIDDEN_DIM];
float output_layer_bias[NUM_CLASSES];

float relu(float x) {
    return x > 0 ? x : 0;
}

int load_weights(const char* filename) {
    FILE* f = fopen(filename, "r");
    if (!f) {
        perror("Failed to open weights file");
        return 0;
    }

    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);
    char* content = malloc(fsize + 1);
    fread(content, 1, fsize, f);
    fclose(f);
    content[fsize] = 0;

    cJSON* json = cJSON_Parse(content);
    if (!json) {
        fprintf(stderr, "Failed to parse JSON\n");
        free(content);
        return 0;
    }

    cJSON* item;
    cJSON* elem;
    int row, col;

    // Load input_layer.weight
    item = cJSON_GetObjectItem(json, "input_layer.weight");
    if (item) {
        row = 0;
        cJSON_ArrayForEach(elem, item) {
            col = 0;
            cJSON* val;
            cJSON_ArrayForEach(val, elem) {
                input_layer_weight[row][col] = val->valuedouble;
                col++;
            }
            row++;
        }
    }

    // Load input_layer.bias
    item = cJSON_GetObjectItem(json, "input_layer.bias");
    if (item) {
        col = 0;
        cJSON* val;
        cJSON_ArrayForEach(val, item) {
            input_layer_bias[col] = val->valuedouble;
            col++;
        }
    }

    // Load hidden_layer.weight
    item = cJSON_GetObjectItem(json, "hidden_layer.weight");
    if (item) {
        row = 0;
        cJSON_ArrayForEach(elem, item) {
            col = 0;
            cJSON* val;
            cJSON_ArrayForEach(val, elem) {
                hidden_layer_weight[row][col] = val->valuedouble;
                col++;
            }
            row++;
        }
    }

    // Load hidden_layer.bias
    item = cJSON_GetObjectItem(json, "hidden_layer.bias");
    if (item) {
        col = 0;
        cJSON* val;
        cJSON_ArrayForEach(val, item) {
            hidden_layer_bias[col] = val->valuedouble;
            col++;
        }
    }

    // Load output_layer.weight
    item = cJSON_GetObjectItem(json, "output_layer.weight");
    if (item) {
        row = 0;
        cJSON_ArrayForEach(elem, item) {
            col = 0;
            cJSON* val;
            cJSON_ArrayForEach(val, elem) {
                output_layer_weight[row][col] = val->valuedouble;
                col++;
            }
            row++;
        }
    }

    // Load output_layer.bias
    item = cJSON_GetObjectItem(json, "output_layer.bias");
    if (item) {
        col = 0;
        cJSON* val;
        cJSON_ArrayForEach(val, item) {
            output_layer_bias[col] = val->valuedouble;
            col++;
        }
    }

    cJSON_Delete(json);
    free(content);
    return 1;
}

int load_image_and_predict(const char* image_file) {
    unsigned int width, height;
    unsigned char* image;
    unsigned int error = lodepng_decode32_file(&image, &width, &height, image_file);

    if (error) {
        fprintf(stderr, "Failed to load image: %u\n", error);
        return -1;
    }

    // Normalize and convert to grayscale
    float input[INPUT_DIM];
    for (int i = 0; i < INPUT_DIM; i++) {
        int idx = i * 4;
        if (idx + 2 < width * height * 4) {
            float r = image[idx] / 255.0f;
            float g = image[idx + 1] / 255.0f;
            float b = image[idx + 2] / 255.0f;
            input[i] = (r + g + b) / 3.0f;
        } else {
            input[i] = 0;
        }
    }
    free(image);

    // Forward pass: input layer
    float hidden[HIDDEN_DIM];
    for (int i = 0; i < HIDDEN_DIM; i++) {
        hidden[i] = input_layer_bias[i];
        for (int j = 0; j < INPUT_DIM; j++) {
            hidden[i] += input_layer_weight[i][j] * input[j];
        }
        hidden[i] = relu(hidden[i]);
    }

    // Forward pass: hidden layer
    float hidden2[HIDDEN_DIM];
    for (int i = 0; i < HIDDEN_DIM; i++) {
        hidden2[i] = hidden_layer_bias[i];
        for (int j = 0; j < HIDDEN_DIM; j++) {
            hidden2[i] += hidden_layer_weight[i][j] * hidden[j];
        }
        hidden2[i] = relu(hidden2[i]);
    }

    // Forward pass: output layer
    float output[NUM_CLASSES];
    for (int i = 0; i < NUM_CLASSES; i++) {
        output[i] = output_layer_bias[i];
        for (int j = 0; j < HIDDEN_DIM; j++) {
            output[i] += output_layer_weight[i][j] * hidden2[j];
        }
    }

    // Find argmax
    int prediction = 0;
    float max_val = output[0];
    for (int i = 1; i < NUM_CLASSES; i++) {
        if (output[i] > max_val) {
            max_val = output[i];
            prediction = i;
        }
    }

    return prediction;
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s weights.json image.png\n", argv[0]);
        return 1;
    }

    if (!load_weights(argv[1])) {
        return 1;
    }

    int prediction = load_image_and_predict(argv[2]);
    if (prediction >= 0 && prediction < NUM_CLASSES) {
        printf("%d\n", prediction);
    } else {
        return 1;
    }

    return 0;
}

